typedef int (*step_fn)(int x, void *ctx);

static int chain_apply(const step_fn *steps, void **ctxs, size_t n, int x) {
    for (size_t i = 0; i < n; ++i)
        x = steps[i](x, ctxs[i]);
    return x;
}

/* steps = { normalize, validate, format } - each a plain C function */
